\section{Introduction}
Iterative maps built from exponentials and logarithms pervade applied
mathematics and the activation/gating functions of machine learning. The
composite $f(x)=e^{a}\log(bx+c)$ has enough analytic structure for a complete
dynamical analysis: existence and uniqueness of equilibria, convergence and its
rate, and guaranteed enclosures. We carry this out below. Here $\log$ is the
natural logarithm and the \emph{natural domain} of $f$ is $\{x:bx+c>0\}$.

\section{Definitions}
\begin{definition}[EML operator]
For $a,b,c\in\R$, $\eml(x)=e^{a}\log(bx+c)$.
\end{definition}
\begin{definition}[Iteration sequence]
Given $x_0$, set $x_{n+1}=\eml(x_n)$.
\end{definition}
\begin{definition}[Contraction data]\label{def:cd}
Reals $a,b,c,\ell,h,\rho$ with $\ell<h$, $0\le\rho<1$, $bx+c>0$ on $[\ell,h]$,
$\eml([\ell,h])\subseteq[\ell,h]$, and $|e^{a}b/(bx+c)|\le\rho$ on $[\ell,h]$.
\end{definition}

\section{Differential structure}
\begin{lemma}[Derivative formula]\label{lem:deriv}
If $bx+c>0$ then $\eml$ is differentiable at $x$ and
$\eml'(x)=\dfrac{e^{a}b}{bx+c}$.
\end{lemma}
\begin{proof}[Proof sketch]
Chain rule: inner affine $bx+c$ has derivative $b$, the logarithm contributes
$1/(bx+c)$ (valid as $bx+c\neq0$), scaled by the constant $e^a$.
\end{proof}

\begin{lemma}[Fixed-point identity]\label{lem:fix}
If $\eml(x^*)=x^*$ then $x^*=e^{a}\log(bx^*+c)$. Moreover if $x^*>0$ and
$bx^*+c>0$ then $bx^*+c>1$.
\end{lemma}
\begin{proof}[Proof sketch]
The identity is the fixed-point equation. If $bx^*+c\le1$ then
$\log(bx^*+c)\le0$, forcing $x^*\le0$, a contradiction.
\end{proof}

\section{Contraction, uniqueness and convergence}
\begin{lemma}[Lipschitz from a derivative bound]\label{lem:lip}
Under Definition~\ref{def:cd}'s positivity and derivative bound, for all
$x,y\in[\ell,h]$, $|\eml(x)-\eml(y)|\le\rho\,|x-y|$.
\end{lemma}
\begin{proof}[Proof sketch]
$[\ell,h]$ is convex and $f$ is differentiable on it with $|f'|\le\rho$; the
convex mean-value inequality gives the Lipschitz estimate.
\end{proof}

\begin{theorem}[Uniqueness]\label{thm:uniq}
With $\rho<1$, $\eml$ has at most one fixed point in $[\ell,h]$.
\end{theorem}
\begin{proof}[Proof sketch]
$|x_1-x_2|=|\eml(x_1)-\eml(x_2)|\le\rho|x_1-x_2|$ and $\rho<1$ force equality.
\end{proof}

\begin{lemma}[Invariance]\label{lem:inv}
If $x_0\in[\ell,h]$ and $f$ is self-mapping there, then $x_n\in[\ell,h]$ for all
$n$ (induction).
\end{lemma}

\begin{lemma}[Geometric decay of steps]\label{lem:decay}
For contraction data and $x_0\in[\ell,h]$,
$|x_{n+1}-x_n|\le\rho^{n}|x_1-x_0|$.
\end{lemma}
\begin{proof}[Proof sketch]
Induction on $n$ using Lemma~\ref{lem:lip} applied to the in-interval iterates
(Lemma~\ref{lem:inv}).
\end{proof}

\begin{theorem}[Convergence to a fixed point]\label{thm:conv}
For contraction data and $x_0\in[\ell,h]$ there exists $x^*$ with $x_n\to x^*$,
$\eml(x^*)=x^*$, and $x^*\in[\ell,h]$.
\end{theorem}
\begin{proof}[Proof sketch]
Lemma~\ref{lem:decay} makes the orbit Cauchy (geometric comparison), so it
converges to some $x^*\in[\ell,h]$ (closedness). Continuity of $f$ on $[\ell,h]$
and passage to the limit in $x_{n+1}=\eml(x_n)$ give $\eml(x^*)=x^*$.
\end{proof}

\begin{remark}
Canonical reductions: $f_{a,1,1}(x)=e^a\log(x+1)$ and $f_{0,b,c}(x)=\log(bx+c)$.
\end{remark}

\section{Certified geometric rate}
\begin{theorem}[A priori error bound]\label{thm:rate}
For contraction data, $x_0\in[\ell,h]$, with limit $x^*$ from
Theorem~\ref{thm:conv},
\[
|x_n-x^*|\;\le\;\frac{|x_1-x_0|\,\rho^{n}}{1-\rho}\qquad(n\in\N),
\]
and this bound tends to $0$, certifying genuine $O(\rho^n)$ convergence.
\end{theorem}
\begin{proof}[Proof sketch]
Sum the geometric tail of the metric form
$\dist(x_n,x_{n+1})\le|x_1-x_0|\rho^n$ and pass to the limit.
\end{proof}

\section{Sharp existence threshold ($b=1$)}
Write the residual $g(x)=f_{a,1,c}(x)-x$.
\begin{lemma}[Residual ceiling]\label{lem:res}
For $x+c>0$, \ $f_{a,1,c}(x)-x\le e^{a}(a-1)+c$, with equality at $x+c=e^a$.
\end{lemma}
\begin{proof}[Proof sketch]
Apply $\log s\le s-1$ to $s=(x+c)/e^a>0$, then multiply by $e^a>0$ and
rearrange.
\end{proof}

\begin{theorem}[Sharp existence law]\label{thm:exist}
For $b=1$: if $e^{a}(a-1)+c<0$ then $f_{a,1,c}$ has no fixed point in $x+c>0$;
conversely, if a fixed point exists in $x+c>0$ then $c\ge e^{a}(1-a)$.
\end{theorem}
\begin{proof}[Proof sketch]
At a fixed point $g=0$, so Lemma~\ref{lem:res} gives $0\le e^a(a-1)+c$;
contrapositively a negative ceiling makes $g<0$ everywhere.
\end{proof}

\begin{corollary}[Falsification of the naive box]\label{cor:box}
For $a=c=\tfrac12,\ b=1$ (inside $(0,1)^2$) there is no fixed point, since
$e^{1/2}(1-\tfrac12)=\tfrac12e^{1/2}\approx0.824>\tfrac12=c$.
\end{corollary}

\begin{theorem}[Neutrality on the threshold]\label{thm:neutral}
At $c=e^{a}(1-a)$, the point $x^*=e^{a}-c$ satisfies $f_{a,1,c}(x^*)=x^*$ and
$f_{a,1,c}'(x^*)=1$.
\end{theorem}
\begin{proof}[Proof sketch]
Then $x^*+c=e^a$, so $f(x^*)=e^a a=x^*$ and $f'(x^*)=e^a/e^a=1$.
\end{proof}

\begin{remark}[Supercritical existence]
For $b=1,c=2,\ 0<a<\tfrac12$ a positive fixed point exists in $(1,3)$ by the
Intermediate Value Theorem ($g(1)>0$, $g(3)<0$ using $e^{1/2}\log5<3$).
\end{remark}

\section{Monotonicity and self-validating enclosure ($b>0$)}
\begin{lemma}[Monotonicity]\label{lem:mono}
If $b>0$ and $bx+c>0$ on $[\ell,h]$ then $\eml$ is nondecreasing there.
\end{lemma}
\begin{proof}[Proof sketch]
$u\le v\Rightarrow\log(bu+c)\le\log(bv+c)$; multiply by $e^a\ge0$.
\end{proof}

\begin{lemma}[Endpoint orbits, bracketing]\label{lem:bracket}
For $b>0$, $n\mapsto f^n(\ell)$ is nondecreasing, $n\mapsto f^n(h)$ is
nonincreasing, and any fixed point $x^*\in[\ell,h]$ obeys
$f^n(\ell)\le x^*\le f^n(h)$ for all $n$.
\end{lemma}

\begin{theorem}[Certified two-sided enclosure]\label{thm:encl}
For contraction data with $b>0$ there is a unique fixed point $x^*\in[\ell,h]$
with $\ell_n:=f^n(\ell)\le x^*\le f^n(h)=:u_n$ for all $n$, $\ell_n\to x^*$,
$u_n\to x^*$, and $u_n-\ell_n\to0$.
\end{theorem}
\begin{proof}[Proof sketch]
Both endpoint orbits converge to fixed points (Theorem~\ref{thm:conv});
uniqueness (Theorem~\ref{thm:uniq}) identifies the limits; Lemma~\ref{lem:bracket}
gives the enclosure and the common limit forces the width to vanish.
\end{proof}

\section{A worked, certified instance}
\begin{example}\label{ex:concrete}
Take $a=1,b=1,c=100,\ \ell=0,\ h=20,\ \rho=1/30$, i.e.\ $f(x)=e\log(x+100)$ on
$[0,20]$. Then $x+100\in[100,120]>0$; $f([0,20])\subseteq[0,20]$ (as
$0\le e\log(x+100)$ and $e\log120<20$); and $|f'(x)|=e/(x+100)\le e/100<1/30$.
The instance is nontrivial since $e^a=e>1$.
\end{example}

\begin{theorem}[End-to-end certified convergence]\label{thm:concrete}
For every $x_0\in[0,20]$ the iteration $x_{n+1}=e\log(x_n+100)$ converges to a
fixed point $x^*\in[0,20]$ ($x^*\approx12.8467$) with
$|x_n-x^*|\le|x_1-x_0|\,(1/30)^n/(1-1/30)$.
\end{theorem}

\section{Discussion and future work}
Existence (Theorem~\ref{thm:exist}), uniqueness/convergence
(Theorems~\ref{thm:uniq},~\ref{thm:conv}), rate (Theorem~\ref{thm:rate}) and
enclosure (Theorem~\ref{thm:encl}) compose into a certified pipeline. The
existence and contraction frontiers coincide on the bifurcation curve
$c=e^a(1-a)$ (Theorem~\ref{thm:neutral}), and the parameter region of tame
dynamics is curved, not a rectangle (Corollary~\ref{cor:box}). Open directions:
the global basin of attraction above threshold; sharp asymptotics of the
contraction ratio as $c\downarrow e^a(1-a)$; real-analytic dependence of the
attractor on $(a,c)$ via the implicit function theorem applied to
$\Phi(x,a,c)=e^a\log(x+c)-x$; and exclusion of genuine period-2 orbits from
strict monotonicity.

\section{Conclusion}
In the supercritical regime the exp--log operator $f(x)=e^a\log(bx+c)$ admits a
unique fixed point, universal convergence on its working interval, an explicit
geometric error certificate, and a self-validating enclosure, with existence
governed by the sharp law $c\ge e^a(1-a)$. This makes EML maps a dependable
primitive for certified iterative computation.

